INSERT INTO conclusion_recommend_management (CREATED_DATE,CREATED_BY,MODIFIED_DATE,MODIFIED_BY,IS_DELETED,MODEL,AGE_TYPE,`TYPE`,GENDER,INDICATOR_FROM,INDICATOR_TO,INDICATOR_AND,VALUE_FROM,VALUE_TO,VALUE_ONE_FROM,VALUE_ONE_TO,CONCLUSION,RECOMMEND) VALUES
	 (NULL,NULL,NULL,NULL,0,'WEIGHT','FROM_0_LESS_THAN_5','FROM_2SD_LESS_THAN_2SD','nu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng của trẻ thuộc mức <strong style="color: #4CCA35;">Bình thường</strong>.</p>','<p>Cân nặng của trẻ phát triển bình thường. Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho trẻ phát triển toàn diện về thể chất và trí não. Bạn hãy cho trẻ thăm khám định kỳ và tham khảo thêm về chế độ ăn của trẻ cho những giai đoạn tiếp theo.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT','FROM_0_LESS_THAN_5','MORE_THAN_3SD','nu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng của trẻ cao hơn so với mức bình thường ở cùng độ tuổi hiện được phân loại vào nhóm "<strong style="color: #E52A1A;">Có nguy cơ thừa cân</strong>".</p>','<p>Bạn cần đưa trẻ đến thăm khám, tư vấn thêm từ các bác sĩ/ chuyên gia dinh dưỡng, đồng thời bạn cũng có thể tham khảo thêm về chế độ ăn cho trẻ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT','FROM_0_LESS_THAN_5','FROM_3SD_LESS_THAN_3SD','nu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng của trẻ nhẹ hơn so với cân nặng bình thường ở cùng độ tuổi, và thuộc mức <strong style="color: #FD9602;">Suy dinh dưỡng nhẹ cân, mức độ vừa</strong>.</p>','<p>Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho trẻ phát triển toàn diện về thể chất và trí não. Bạn cần tư vấn sớm bác sĩ/ chuyên gia dinh dưỡng về chế độ ăn của trẻ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT','FROM_0_LESS_THAN_5','FROM_2SD_LESS_THAN_3SD','nu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng của trẻ cao hơn so với mức bình thường ở cùng độ tuổi, và thuộc mức <strong style="color: #F5540A;">Có nguy cơ thừa cân</strong>.</p>','<p>Bạn cần đưa trẻ đến thăm khám, tư vấn thêm từ các bác sĩ/ chuyên gia dinh dưỡng, đồng thời bạn cũng có thể tham khảo thêm về chế độ ăn cho trẻ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT','FROM_0_LESS_THAN_5','LESS_3SD','nu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng của trẻ nhẹ hơn nhiều so với cân nặng bình thường ở cùng độ tuổi, thuộc mức <strong style="color: #1AA8E3;">Suy dinh dưỡng nhẹ cân, mức độ nặng</strong>.</p>','<p>Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho trẻ phát triển toàn diện về thể chất và trí não. Bạn cần tư vấn sớm bác sĩ/ chuyên gia dinh dưỡng về chế độ ăn của trẻ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_2_LESS_THAN_5','MORE_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ thuộc mức <strong style="color: #E52A1A;">Béo phì</strong>.</p>','<p>Bạn cần đưa trẻ đến thăm khám, tư vấn thêm từ các bác sĩ/ chuyên gia dinh dưỡng, đồng thời bạn cũng có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_0_LESS_THAN_2','FROM_3SD_LESS_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ theo mức <strong style="color: #00ADF5;">Suy dinh dưỡng gầy còm, mức độ vừa</strong>.</p>','<p>Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho trẻ phát triển phát triển toàn diện về thể chất và trí não. Bạn cần tư vấn sớm bác sĩ/ chuyên gia dinh dưỡng về chế độ ăn của trẻ</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_2_LESS_THAN_5','FROM_2SD_LESS_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ thuộc mức <strong style="color: #FD9602;">Thừa cân</strong>.</p>','<p>Bạn cần đưa trẻ thăm khám, tư vấn thêm từ các bác sĩ/ chuyên gia dinh dưỡng, đồng thời bạn cũng có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_0_LESS_THAN_2','FROM_2SD_LESS_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ theo mức <strong style="color: #FD9602;">Thừa cân</strong>.</p>','<p>Bạn cần đưa trẻ thăm khám, tư vấn thêm từ các bác sĩ/ chuyên gia dinh dưỡng, đồng thời bạn cũng có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_2_LESS_THAN_5','FROM_3SD_LESS_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ thuộc mức <strong style="color: #00A9F0;">Suy dinh dưỡng gầy còm, mức độ vừa</strong>.</p>','<p>Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho trẻ phát triển phát triển toàn diện về thể chất và trí não. Bạn cần tư vấn sớm bác sĩ/ chuyên gia dinh dưỡng về chế độ ăn của trẻ</p>');
