	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_0_LESS_THAN_2','MORE_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ thuộc mức <strong style="color: #E52A1A;">Béo phì</strong>.</p>','<p>Bạn cần đưa trẻ đến thăm khám, tư vấn thêm từ các bác sĩ/ chuyên gia dinh dưỡng, đồng thời bạn cũng có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_0_LESS_THAN_2','FROM_2SD_LESS_THAN_2SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ thuộc mức <strong style="color: #4CCA35;">Bình thường</strong>.</p>','<p>Cân nặng, chiều cao của trẻ phát triển bình thường. Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho trẻ phát triển toàn diện về thể chất và trí não. Bạn hãy cho trẻ thăm khám định kỳ và tham khảo thêm về chế độ ăn của trẻ cho những giai đoạn tiếp theo nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_12_LESS_THAN_20','MORE_THAN_2SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ hiện thuộc mức <strong style="color: rgb(230, 0, 0);">Béo phì</strong>.</p>','<p>Trẻ bị béo phì cần đi khám dinh dưỡng để được hướng dẫn điều trị thêm. Nên giữ đứng cân hoặc tăng cân chậm lại nhưng vẫn đảm bảo tăng chiều cao tốt, nếu cần giảm cân phải có sự theo dõi của Bác sĩ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_12_LESS_THAN_20','FROM_3SD_LESS_THAN_2SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ hiện thuộc mức <strong style="color: rgb(178, 178, 0);">Suy dinh dưỡng gầy còm, mức độ vừa</strong>.</p>','<p>Bạn cần đưa trẻ đi khám tìm nguyên nhân suy dinh dưỡng để điều trị sớm. Đồng thời, để phát triển tối ưu, tăng cân, tăng chiều cao tốt bạn có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_12_LESS_THAN_20','LESS_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ hiện thuộc mức <strong style="color: rgb(0, 102, 204);">Suy dinh dưỡng gầy còm, mức độ nặng.</strong></p>','<p>Bạn cần đưa trẻ đi khám tìm nguyên nhân suy dinh dưỡng để điều trị sớm. Đồng thời, để phát triển tối ưu, tăng cân, tăng chiều cao tốt bạn có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_12_LESS_THAN_20','FROM_2SD_LESS_THAN_1SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ hiện thuộc mức <strong style="color: rgb(0, 138, 0);">Bình thường</strong>.</p>','<p>Trẻ đang phát triển tốt. Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho bé phát triển toàn diện về thể chất và trí não. Bạn hãy cho trẻ thăm khám định kỳ và tham khảo thêm về chế độ ăn của trẻ cho những giai đoạn tiếp theo nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_12_LESS_THAN_20','FROM_1SD_LESS_THAN_2SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ hiện thuộc mức <strong style="color: rgb(240, 102, 102);">Thừa cân</strong>.</p>','<p>Trẻ bị thừa cân cần đi khám dinh dưỡng để được hướng dẫn điều trị thêm. Nên giữ đứng cân hoặc tăng cân chậm lại nhưng vẫn đảm bảo tăng chiều cao tốt, nếu cần giảm cân phải có sự theo dõi của Bác sĩ.</p>');
INSERT INTO conclusion_recommend_management (CREATED_DATE,CREATED_BY,MODIFIED_DATE,MODIFIED_BY,IS_DELETED,MODEL,AGE_TYPE,`TYPE`,GENDER,INDICATOR_FROM,INDICATOR_TO,INDICATOR_AND,VALUE_FROM,VALUE_TO,VALUE_ONE_FROM,VALUE_ONE_TO,CONCLUSION,RECOMMEND) VALUES
	 (NULL,NULL,NULL,NULL,0,'AXIT_URIC','FROM_20_LESS_THEN_70','MORE_THAN_NORMAL','nu','MORE_THAN',NULL,NULL,360.0,NULL,NULL,NULL,'<p>Hàm lượng axit uric lần đo này của bạn hiện được phân loại <strong style="color: rgb(255, 153, 0);">Cao hơn ngưỡng bình thường</strong>.</p>','<p>Kết quả chỉ có giá trị tham khảo. Bạn nên khám chuyên khoa và tư vấn thêm bác sĩ về tình trạng axit uric và sức khỏe của bạn, cũng như tư vấn về chế độ ăn để hỗ trợ duy trì chỉ số axit uric trong ngưỡng bình thường nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'AXIT_URIC','FROM_20_LESS_THEN_70','NORMAL','nu','ABOUT',NULL,NULL,150.0,360.0,NULL,NULL,'<p>Hàm lượng axit uric lần đo này của bạn hiện được phân loại trong ngưỡng <strong style="color: rgb(0, 138, 0);">Bình thường</strong>.</p>','<p>Kết quả chỉ có giá trị tham khảo. Bạn hãy khám định kỳ, tiếp tục duy trì lối sống lành mạnh, đồng thời tham khảo hướng dẫn về chế độ ăn cân bằng dinh dưỡng &amp; hoạt động thể chất từ Phần mềm để duy trì sức khỏe và phòng ngừa các bệnh không lây nhiễm nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'AXIT_URIC','EQUAL_MORE_THAN_70','MORE_THAN_NORMAL','nu','MORE_THAN',NULL,NULL,360.0,NULL,NULL,NULL,'<p>Hàm lượng axit uric lần đo này của bạn hiện được phân loại <strong style="color: rgb(255, 153, 0);">Cao hơn ngưỡng bình thường</strong>.</p>','<p>Kết quả chỉ có giá trị tham khảo. Bạn nên khám chuyên khoa và tư vấn thêm bác sĩ về tình trạng axit uric và sức khỏe của bạn, cũng như tư vấn về chế độ ăn để hỗ trợ duy trì chỉ số axit uric trong ngưỡng bình thường nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'AXIT_URIC','FROM_20_LESS_THEN_70','LESS_THAN_MORMAL','nu','LESS_THAN',NULL,NULL,150.0,NULL,NULL,NULL,'<p>Hàm lượng axit uric lần đo này của bạn hiện được phân loại <strong style="color: rgb(0, 102, 204);">Thấp hơn mức bình thường</strong>.</p>','<p>Kết quả chỉ có giá trị tham khảo. Bạn hãy tư vấn thêm bác sĩ chuyên khoa khi đi khám định kỳ bạn nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'AXIT_URIC','EQUAL_MORE_THAN_70','NORMAL','nu','ABOUT',NULL,NULL,150.0,360.0,NULL,NULL,'<p>Hàm lượng axit uric lần đo này của bạn hiện được phân loại trong ngưỡng <strong style="color: rgb(0, 138, 0);">Bình thường</strong>.</p>','<p>Kết quả chỉ có giá trị tham khảo. Bạn hãy khám định kỳ, tiếp tục duy trì lối sống lành mạnh, đồng thời tham khảo hướng dẫn về chế độ ăn cân bằng dinh dưỡng &amp; hoạt động thể chất từ Phần mềm để duy trì sức khỏe và phòng ngừa các bệnh không lây nhiễm nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'AXIT_URIC','EQUAL_MORE_THAN_70','LESS_THAN_MORMAL','nu','LESS_THAN',NULL,NULL,150.0,NULL,NULL,NULL,'<p>Hàm lượng axit uric lần đo này của bạn hiện được phân loại <strong style="color: rgb(0, 102, 204);">Thấp hơn mức bình thường</strong>.</p>','<p>Kết quả chỉ có giá trị tham khảo. Bạn hãy tư vấn thêm bác sĩ chuyên khoa khi đi khám định kỳ bạn nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'CHOL','EQUAL_MORE_THAN_70','LESS_THAN_MORMAL',NULL,'LESS_THAN',NULL,NULL,3.9,NULL,NULL,NULL,'<p>Hàm lượng Cholesterol lần đo này của bạn thuộc mức <strong style="color: rgb(0, 102, 204);">Thấp hơn bình thường</strong>.&nbsp;&nbsp;</p>','<p>Kết quả này chỉ có giá trị tham khảo. Bạn cần thăm khám thêm chuyên khoa để được chẩn đoán, điều trị và tư vấn sức khỏe chính xác.</p>'),
