	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_20_LESS_THEN_70','OBESITY_PRE',NULL,'ABOUT',NULL,NULL,25.0,29.99,NULL,NULL,'<p>Chỉ số BMI đo được của bạn hiện thuộc mức <strong style="color: rgb(178, 178, 0);">Tiền béo phì</strong>.</p>','<p>Bạn đang dư thừa cân nặng so với chiều cao hiện có. Bạn cần đi khám dinh dưỡng để tìm nguyên nhân và điều trị tích cực để kịp thời ngăn ngừa các biến chứng. Đồng thời, bạn hãy thay đổi lối sống, chế độ ăn hằng ngày để cải thiện sức khỏe tốt.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_20_LESS_THEN_70','OBESITY_THREE',NULL,'MORE_THAN_OR_EQUAL',NULL,NULL,40.0,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của bạn hiện thuộc mức <strong style="color: rgb(230, 0, 0);">Béo phì cấp độ III</strong>.</p>','<p>Bạn đang dư thừa cân nặng so với chiều cao hiện có. Bạn cần đi khám dinh dưỡng để tìm nguyên nhân và điều trị tích cực, để kịp thời ngăn ngừa các biến chứng. Đồng thời, bạn hãy thay đổi lối sống, chế độ ăn hằng ngày để cải thiện sức khỏe tốt.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_20_LESS_THEN_70','UNDERWEGHT_ONE',NULL,'ABOUT',NULL,NULL,17.0,18.49,NULL,NULL,'<p>Chỉ số BMI lần đo này của bạn thuộc mức <strong style="color: rgb(102, 163, 224);">Gầy độ 1</strong>.</p>','<p>Bạn đang thiếu cân nặng so với chiều cao hiện có. Bạn cần đi khám Bác sĩ tìm nguyên nhân để điều trị. Đồng thời, bạn hãy thay đổi lối sống, chế độ ăn hằng ngày để cải thiện sức khỏe tốt, ngăn chặn các bệnh lý khác.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_20_LESS_THEN_70','OBESITY_ONE',NULL,'ABOUT',NULL,NULL,30.0,34.99,NULL,NULL,'<p>Chỉ số BMI đo được của bạn hiện được phân loại vào nhóm "<strong style="color: rgb(255, 194, 102);">Béo phì cấp độ I</strong>".</p>','<p>Bạn đang dư thừa cân nặng so với chiều cao hiện có. Bạn cần đi khám dinh dưỡng để tìm nguyên nhân và điều trị tích cực để kịp thời ngăn ngừa các biến chứng. Đồng thời, bạn hãy thay đổi lối sống, chế độ ăn hằng ngày để cải thiện sức khỏe tốt.</p>');
