	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_2_LESS_THAN_5','FROM_3SD_LESS_THAN_3SD','nu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ thuộc mức <strong style="color: rgb(0, 173, 245);">Suy dinh dưỡng gầy còm, mức độ vừa</strong>.</p>','<p>Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho trẻ phát triển phát triển toàn diện về thể chất và trí não. Bạn cần tư vấn sớm bác sĩ/ chuyên gia dinh dưỡng về chế độ ăn của trẻ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_0_LESS_THAN_2','FROM_3SD_LESS_THAN_3SD','nu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ thuộc mức <strong style="color: rgb(0, 173, 245);">Suy dinh dưỡng gầy còm, mức độ vừa.</strong></p>','<p>Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho trẻ phát triển phát triển toàn diện về thể chất và trí não. Bạn cần tư vấn sớm bác sĩ/ chuyên gia dinh dưỡng về chế độ ăn của trẻ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_0_LESS_THAN_2','MORE_THAN_3SD','nu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ thuộc mức <strong style="color: rgb(229, 42, 26);">Béo phì</strong>.</p>','<p>Bạn cần đưa trẻ đến thăm khám, tư vấn thêm từ các bác sĩ/ chuyên gia dinh dưỡng, đồng thời bạn cũng có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT_HEIGHT','FROM_0_LESS_THAN_2','FROM_2SD_LESS_THAN_2SD','nu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng theo chiều dài/ chiều cao của trẻ thuộc mức <strong style="color: rgb(76, 202, 53);">Bình thường</strong>.</p>','<p>Cân nặng, chiều cao của trẻ phát triển bình thường. Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho bé phát triển toàn diện về thể chất và trí não. Bạn hãy cho trẻ thăm khám định kỳ và tham khảo thêm về chế độ ăn của trẻ cho những giai đoạn tiếp theo nhé.</p>');
