INSERT INTO conclusion_recommend_management (CREATED_DATE,CREATED_BY,MODIFIED_DATE,MODIFIED_BY,IS_DELETED,MODEL,AGE_TYPE,`TYPE`,GENDER,INDICATOR_FROM,INDICATOR_TO,INDICATOR_AND,VALUE_FROM,VALUE_TO,VALUE_ONE_FROM,VALUE_ONE_TO,CONCLUSION,RECOMMEND) VALUES
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_5_LESS_THAN_12','LESS_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ thuộc mức <strong style="color: rgb(26, 168, 227);">Suy dinh dưỡng gầy còm, mức độ nặng</strong>.</p>','<p>Bạn cần đưa trẻ đi khám tìm nguyên nhân suy dinh dưỡng để điều trị sớm. Đồng thời, để phát triển tối ưu, tăng cân, tăng chiều cao tốt, bạn có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ, giúp trẻ có sức khỏe tốt hơn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_5_LESS_THAN_12','MORE_THAN_2SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ thuộc mức <strong style="color: rgb(229, 42, 26);">Béo phì</strong>.</p>','<p>Trẻ bị béo phì cần đi khám dinh dưỡng để được hướng dẫn điều trị thêm. Nên giữ đúng cân hoặc tăng cân chậm lại nhưng vẫn đảm bảo tăng chiều cao tốt, nếu cần giảm cân phải có sự theo dõi của Bác sĩ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_5_LESS_THAN_12','FROM_1SD_LESS_THAN_2SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ thuộc mức <strong style="color: rgb(245, 84, 10);">Thừa cân</strong>.</p>','<p>Trẻ bị thừa cân cần đi khám dinh dưỡng để được hướng dẫn điều trị thêm. Nên giữ đúng cân hoặc tăng cân chậm lại nhưng vẫn đảm bảo tăng chiều cao tốt, nếu cần giảm cân phải có sự theo dõi của Bác sĩ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_5_LESS_THAN_12','FROM_2SD_LESS_THAN_1SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ thuộc mức <strong style="color: rgb(76, 202, 53);">Bình thường</strong>.</p>','<p>Trẻ đang phát triển tốt. Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho bé phát triển toàn diện về thể chất và trí não. Bạn hãy cho trẻ thăm khám định kỳ và tham khảo thêm về chế độ ăn của trẻ cho những giai đoạn tiếp theo nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_5_LESS_THAN_12','FROM_3SD_LESS_THAN_2SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ hiện thuộc mức <strong style="color: rgb(253, 150, 2);">Suy dinh dưỡng gầy còm, mức độ vừa</strong><span style="color: rgb(255, 153, 0);">.</span></p>','<p>Bạn cần đưa trẻ đi khám tìm nguyên nhân suy dinh dưỡng để điều trị sớm. Đồng thời, để phát triển tối ưu, tăng cân, tăng chiều cao tốt bạn có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_5_LESS_THAN_12','FROM_3SD_LESS_THAN_2SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>1</p>','<p>1</p>'),
	 (NULL,NULL,NULL,NULL,0,'BMI','FROM_5_LESS_THAN_12','FROM_3SD_LESS_THAN_2SD','nu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chỉ số BMI đo được của trẻ hiện thuộc mức <strong style="color: rgb(253, 150, 2);">Suy dinh dưỡng gầy còm, mức độ vừa</strong><span style="color: rgb(255, 153, 0);">.</span></p>','<p>Bạn cần đưa trẻ đi khám tìm nguyên nhân suy dinh dưỡng để điều trị sớm. Đồng thời, để phát triển tối ưu, tăng cân, tăng chiều cao tốt bạn có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
