	 (NULL,NULL,NULL,NULL,0,'AXIT_URIC','EQUAL_MORE_THAN_70','MORE_THAN_NORMAL','nam','MORE_THAN',NULL,NULL,420.0,NULL,NULL,NULL,'<p>Hàm lượng axit uric lần đo này của bạn hiện được phân loại <strong style="color: rgb(255, 153, 0);">Cao hơn ngưỡng bình thường</strong>.</p>','<p>Kết quả chỉ có giá trị tham khảo. Bạn nên khám chuyên khoa và tư vấn thêm bác sĩ về tình trạng axit uric và sức khỏe của bạn, cũng như tư vấn về chế độ ăn để hỗ trợ duy trì chỉ số axit uric trong ngưỡng bình thường nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'AXIT_URIC','EQUAL_MORE_THAN_70','NORMAL','nam','MORE_THAN',NULL,NULL,1.0,NULL,NULL,NULL,'<p><br></p>','<p>test</p>'),
	 (NULL,NULL,NULL,NULL,0,'AXIT_URIC','FROM_20_LESS_THEN_70','MORE_THAN_NORMAL','nam','MORE_THAN',NULL,NULL,420.0,NULL,NULL,NULL,'<p>Hàm lượng axit uric lần đo này của bạn hiện được phân loại <strong style="color: rgb(255, 153, 0);">Cao hơn ngưỡng bình thường</strong>.</p>','<p>Kết quả chỉ có giá trị tham khảo. Bạn nên khám chuyên khoa và tư vấn thêm bác sĩ về tình trạng axit uric và sức khỏe của bạn, cũng như tư vấn về chế độ ăn để hỗ trợ duy trì chỉ số axit uric trong ngưỡng bình thường nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'AXIT_URIC','FROM_20_LESS_THEN_70','NORMAL','nam','ABOUT',NULL,NULL,180.0,420.0,NULL,NULL,'<p>Hàm lượng axit uric lần đo này của bạn hiện được phân loại trong ngưỡng <strong style="color: rgb(0, 138, 0);">Bình thường</strong>.</p>','<p>Kết quả chỉ có giá trị tham khảo. Bạn hãy khám định kỳ, tiếp tục duy trì lối sống lành mạnh, đồng thời tham khảo hướng dẫn về chế độ ăn cân bằng dinh dưỡng &amp; hoạt động thể chất từ Phần mềm để duy trì sức khỏe và phòng ngừa các bệnh không lây nhiễm nhé.</p>');
