	 (NULL,NULL,NULL,NULL,0,'HOSPITAL','FROM_20_LESS_THEN_70','BLOOD_PRESSURE_TWO',NULL,'ABOUT','ABOUT','or',160.0,179.0,100.0,109.0,'<p>Chỉ số huyết áp đo được của bạn thuộc mức <strong style="color: rgb(161, 0, 0);">Tăng huyết áp độ 2</strong>.</p>','<p>Bạn nên khám chuyên khoa và tư vấn thêm bác sĩ về tình trạng huyết áp và sức khỏe của bạn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'HOSPITAL','EQUAL_MORE_THAN_70','BLOOD_PRESSURE_TWO',NULL,'ABOUT','ABOUT','or',160.0,179.0,100.0,105.0,'<p>Chỉ số huyết áp đo được của bạn thuộc mức <strong style="color: rgb(161, 0, 0);">Tăng huyết áp độ 2</strong>.</p>','<p>Bạn nên khám chuyên khoa và tư vấn thêm bác sĩ về tình trạng huyết áp và sức khỏe của bạn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'HOSPITAL','FROM_20_LESS_THEN_70','BLOOD_PRESSURE_MAX',NULL,'MORE_THAN','MORE_THAN','and',1.0,NULL,1.0,NULL,'<p>1</p>','<p>1</p>'),
	 (NULL,NULL,NULL,NULL,0,'HEIGHT','FROM_0_LESS_THAN_5','FROM_2SD_LESS_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chiều cao/chiều dài đo được của trẻ thuộc mức <strong style="color: rgb(255, 153, 0);">Cao hơn so với tuổi</strong></p>','<p>Chiều cao/chiều dài của trẻ cao hơn so với chuẩn tháng tuổi của trẻ. Để đánh giá chính xác tình trạng dinh dưỡng của trẻ, bạn có thể tham khảo thêm biểu đồ Cân nặng theo chiều dài/ chiều cao. Dinh dưỡng đúng và đủ ở mỗi giai đoạn của bé sẽ đảm bảo cho trẻ phát triển toàn diện về thể chất và trí não. Bạn hãy cho trẻ thăm khám định kỳ và tham khảo thêm về chế độ ăn của trẻ cho những giai đoạn tiếp theo nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'HEIGHT','FROM_0_LESS_THAN_5','FROM_3SD_LESS_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chiều cao/chiều dài của trẻ thấp hơn so với chiều cao bình thường ở cùng độ tuổi, và thuộc mức <strong style="color: rgb(102, 163, 224);">Suy dinh dưỡng thấp còi.&nbsp;</strong></p>','<p>Bạn cần đưa trẻ đi khám và tư vấn tìm nguyên nhân suy dinh dưỡng để điều trị sớm. Đồng thời để phát triển tối ưu, tăng cân tốt bạn có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
	 (NULL,NULL,NULL,NULL,0,'HEIGHT','FROM_0_LESS_THAN_5','FROM_2SD_LESS_THAN_2SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chiều cao/chiều dài đo được của trẻ thuộc mức <strong style="color: rgb(0, 138, 0);">Bình thường.&nbsp;</strong></p>','<p>Chiều cao/chiều dài của trẻ phát triển bình thường. Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho bé phát triển toàn diện về thể chất và trí não. Bạn hãy cho trẻ thăm khám định kỳ và tham khảo thêm về chế độ ăn của trẻ cho những giai đoạn tiếp theo nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'HEIGHT','FROM_0_LESS_THAN_5','MORE_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chiều cao/chiều dài đo được của trẻ đang có xu hướng <strong style="color: rgb(230, 0, 0);">Cao hơn so với tuổi</strong></p>','<p>Chiều cao/chiều dài rất cao, cao hơn so với chuẩn tháng tuổi của trẻ. Kiểm tra rối loạn nội tiết nếu trẻ cao bất thường mà không có yếu tố di truyền. Để đánh giá chính xác tình trạng dinh dưỡng của trẻ, bạn có thể tham khảo thêm biểu đồ Cân nặng theo chiều dài/ chiều cao. Dinh dưỡng đúng và đủ ở mỗi giai đoạn của bé sẽ đảm bảo cho trẻ phát triển toàn diện về thể chất và trí não. Bạn hãy cho trẻ thăm khám định kỳ và tham khảo thêm về chế độ ăn của trẻ cho những giai đoạn tiếp theo nhé.&nbsp;</p>'),
	 (NULL,NULL,NULL,NULL,0,'HEIGHT','FROM_0_LESS_THAN_5','LESS_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Chiều cao/chiều dài của trẻ thấp hơn nhiều so với chiều cao bình thường ở cùng độ tuổi, và thuộc mức <strong style="color: rgb(0, 71, 178);">Suy dinh dưỡng thấp còi, mức độ nặng.</strong><span style="color: rgb(0, 71, 178);">&nbsp;</span></p>','<p>Bạn cần đưa trẻ đi khám và tư vấn tìm nguyên nhân suy dinh dưỡng để điều trị sớm. Đồng thời để phát triển tối ưu, tăng cân tốt bạn có thể tham khảo thêm về hướng dẫn chế độ ăn cho trẻ giúp trẻ có sức khỏe tốt hơn.</p>'),
