	 (NULL,NULL,NULL,NULL,0,'WEIGHT','FROM_0_LESS_THAN_5','FROM_2SD_LESS_THAN_2SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng của trẻ thuộc mức <strong style="color: rgb(76, 202, 53);">Bình thường</strong>.</p>','<p>Cân nặng của trẻ phát triển bình thường.</p><p>Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho bé phát triển toàn diện về thể chất và trí não. Bạn hãy cho trẻ thăm khám định kỳ và tham khảo thêm về chế độ ăn của trẻ cho những giai đoạn tiếp theo nhé.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT','FROM_0_LESS_THAN_5','FROM_2SD_LESS_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng của trẻ cao hơn so với mức bình thường ở cùng độ tuổi và thuộc mức <strong style="color: rgb(245, 84, 10);">Có nguy cơ thừa cân</strong>.</p>','<p>Bạn cần đưa trẻ đến thăm khám, tư vấn thêm từ các bác sĩ/ chuyên gia dinh dưỡng, đồng thời bạn cũng có thể tham khảo thêm về chế độ ăn của trẻ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT','FROM_0_LESS_THAN_5','MORE_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng của trẻ cao hơn so với mức bình thường ở cùng độ tuổi hiện được phân loại vào nhóm <strong style="color: rgb(229, 42, 26);">Có nguy cơ thừa cân</strong>.</p>','<p>Bạn cần đưa trẻ đến thăm khám, tư vấn thêm từ các bác sĩ/ chuyên gia dinh dưỡng, đồng thời bạn cũng có thể tham khảo thêm về chế độ ăn cho trẻ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT','FROM_0_LESS_THAN_5','LESS_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng lần này của trẻ nhẹ hơn nhiều so với cân nặng bình thường ở cùng độ tuổi, và thuộc mức <strong style="color: rgb(26, 168, 227);">Suy dinh dưỡng nhẹ cân, mức độ nặng</strong>.</p>','<p>Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho trẻ phát triển phát triển toàn diện về thể chất và trí não. Bạn cần tư vấn sớm bác sĩ/ chuyên gia dinh dưỡng về chế độ ăn của trẻ.</p>'),
	 (NULL,NULL,NULL,NULL,0,'WEIGHT','FROM_0_LESS_THAN_5','FROM_3SD_LESS_THAN_3SD','nam',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<p>Cân nặng lần này của trẻ nhẹ hơn so với cân nặng bình thường ở cùng độ tuổi, và thuộc mức <strong style="color: rgb(253, 150, 2);">Suy dinh dưỡng nhẹ cân, mức độ vừa</strong>.</p>','<p>Dinh dưỡng đúng và đủ ở mỗi giai đoạn của trẻ sẽ đảm bảo cho trẻ phát triển phát triển toàn diện về thể chất và trí não. Bạn cần tư vấn sớm bác sĩ/ chuyên gia dinh dưỡng về chế độ ăn của trẻ.</p>');
